package org.lumen.airplay.cast;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * The model table of the casting screen (assets/cast/models.tsv, generated by tools/devices/cast_models.py from
 * devices/&lt;c&gt;/cast.conf and device.conf): model code, codename, ABI and whether the 4K mirroring quality is
 * offered. Keyed on ro.boot.xgimi.modelname. A model the table does not know gets no 4K option.
 */
public final class CastModels {
    /** One model row. */
    public static final class Model {
        public final String code, codename, abi;
        public final boolean mirror4k;

        Model(String code, String codename, String abi, boolean mirror4k) {
            this.code = code;
            this.codename = codename;
            this.abi = abi;
            this.mirror4k = mirror4k;
        }
    }

    /** What an unknown model reads as: no 4K mirroring offered. */
    public static final Model UNKNOWN = new Model("", "", "", false);

    private final Map<String, Model> rows;

    private CastModels(Map<String, Model> rows) {
        this.rows = Collections.unmodifiableMap(rows);
    }

    /** Parses the table; a malformed line is an error (the generator writes exactly four columns). */
    public static CastModels parse(String tsv) {
        Map<String, Model> m = new LinkedHashMap<>();
        for (String raw : tsv.split("\n")) {
            String line = raw.trim();
            if (line.isEmpty() || line.startsWith("#")) continue;
            String[] f = line.split("\t");
            if (f.length != 4 || !("0".equals(f[3]) || "1".equals(f[3]))) {
                throw new IllegalArgumentException("cast models: bad line " + line);
            }
            m.put(f[0], new Model(f[0], f[1], f[2], "1".equals(f[3])));
        }
        return new CastModels(m);
    }

    /** The row of {@code bootModel} (ro.boot.xgimi.modelname), {@link #UNKNOWN} when absent. */
    public Model find(String bootModel) {
        Model r = bootModel == null ? null : rows.get(bootModel.trim());
        return r == null ? UNKNOWN : r;
    }

    public int size() { return rows.size(); }
}
